// Some portions generated by Codex
/** The lexical range contract shared by loaded values and generated repository filters. */
export type RangeKind = "number" | "date";

// Ranges intentionally accept numeric text in every literal datatype, including strings and language strings.
export const NUMBER_LEXICAL = "[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?";
const CLOCK = "([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]+)?|24:00:00([.]0+)?";
const TIMEZONE = "(Z|[+-]((0[0-9]|1[0-3]):[0-5][0-9]|14:00))";
export const DATE_LEXICAL = `-?[0-9]{4}(-[0-9]{2}(-[0-9]{2}(T(${CLOCK}))?)?)?${TIMEZONE}?`;
const NUMBER = new RegExp(`^${NUMBER_LEXICAL}$`);
const DATE = new RegExp(`^${DATE_LEXICAL}$`);

/** Finite decimal/scientific numbers, or an ISO calendar day (short dates start at January/the month's first day). */
export function parseRangeValue(kind: RangeKind, value: string): number {
  const text = value.trim();
  if (kind === "number") {
    const number = NUMBER.test(text) ? Number(text) : NaN;
    return Number.isFinite(number) ? number : NaN;
  }
  if (!DATE.test(text)) {
    return NaN;
  }
  const parts = /^(-?[0-9]{4})(?:-([0-9]{2})(?:-([0-9]{2}))?)?/.exec(text)!;
  const year = Number(parts[1]);
  const month = Number(parts[2] ?? "1");
  const day = Number(parts[3] ?? "1");
  if (year === 0 || month < 1 || month > 12 || day < 1 || day > 31) {
    return NaN;
  }
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(0, 0, 0, 0);
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
    ? date.getTime()
    : NaN;
}

/** The calendar day used by range controls and date casts, including four-digit negative years. */
export function formatRangeDay(value: number) {
  const date = new Date(value);
  const year = date.getUTCFullYear();
  const yearText = `${year < 0 ? "-" : ""}${String(Math.abs(year)).padStart(4, "0")}`;
  const monthText = String(date.getUTCMonth() + 1).padStart(2, "0");
  const dayText = String(date.getUTCDate()).padStart(2, "0");
  return `${yearText}-${monthText}-${dayText}`;
}

/** SPARQL trims the same ECMAScript whitespace as String.trim(), including non-ASCII whitespace. */
export function rangeLexicalSparql(variable: string) {
  const space = "\\\\s\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000\\ufeff";
  return `REPLACE(STR(${variable}), "^[${space}]+|[${space}]+$", "")`;
}

/** Discard a dateTime's clock and timezone; the date facet selects the calendar day written in the literal. */
export function rangeDaySparql(text: string) {
  const year = `REPLACE(${text}, "^(-?[0-9]{4}).*$", "$1")`;
  const month = `IF(REGEX(${text}, "^-?[0-9]{4}-[0-9]{2}"), REPLACE(${text}, "^-?[0-9]{4}-([0-9]{2}).*$", "$1"), "01")`;
  const day = `IF(REGEX(${text}, "^-?[0-9]{4}-[0-9]{2}-[0-9]{2}"), REPLACE(${text}, "^-?[0-9]{4}-[0-9]{2}-([0-9]{2}).*$", "$1"), "01")`;
  return `<http://www.w3.org/2001/XMLSchema#date>(CONCAT(${year}, "-", ${month}, "-", ${day}))`;
}
